<script setup>
/**
 * ForBusiness.vue — the "Bookboll for Business" recruitment landing page.
 *
 * Entry point of the provider funnel: recruitment banner → THIS PAGE → /signup (account
 * creation) → website setup → first location + listing/program → provider dashboard.
 *
 * Rendered bare (meta.area = 'auth'), indexable, own useSeo (keyword-targeted at sports
 * facility owners: "booking software", "free booking website", court/padel/gym/academy terms).
 * Structured data: SoftwareApplication + FAQPage JSON-LD (passed to useSeo as an array —
 * stringified into one script tag). One keyword-rich h1; h2 per section; 12-question FAQ
 * accordion mirrored 1:1 in the FAQPage LD; crawl-links row (/venues /memberships /terms
 * /signup) above the footer. Colours are FIXED to the recruit-banner teal theme — do NOT
 * swap for --brand vars.
 *
 * Copy stays audited-accurate: loyalty is marketplace-only, deposits/wallet mechanics and the
 * contact-only memberships are disclosed, steps mirror the real funnel,
 * and CTAs are auth-aware (signed-in providers see "Open my dashboard").
 */
import { ref, computed } from 'vue'
import { useSeo, faqLd } from '../lib/seo.js'
import { BRAND_APEX } from '../lib/brand.js'
import { authUser } from '../lib/auth.js'
import { adminLoginUrl, adminDashboardUrl } from '../lib/crossApp.js'
import { webBaseUrl } from '../lib/appBase.js'
import BusinessHeader from '../components/BusinessHeader.vue'
import {
  Store, Globe, Check, ArrowRight, CalendarCheck, CreditCard, Repeat, UserPlus, MapPin, Wallet, Search, ChevronDown, Palette, Link2, Smartphone, CheckCircle2,
} from 'lucide-vue-next'

// Money-accuracy: every number below is verified in code — 15% default marketplace
// commission (lib/approvalState.js PLATFORM_COMMISSION), Premium $588/year (lib/premium.js
// PREMIUM_YEARLY_TOTAL), custom domain = one-time fee (Brand.vue DOMAIN_FEE; price not quoted here).
// Never promise refunds; commission applies to marketplace and own-website bookings.
const FAQS = [
  { q: 'How much does Bookboll cost for a sports facility?',
    a: 'Getting started is free — no setup fees and no monthly fee for the core platform. Booking commissions apply on your website and the Bookboll marketplace. Free merchants pay the standard rate; paid Premium merchants use the configured Premium rate on their own-website bookings. Rates vary by country and listing, and your dashboard shows yours. Optional extras: a custom domain (one-time fee) and a Premium plan ($588/year, billed annually with no free trial) for advanced marketing and export features.' },
  { q: 'What is the Bookboll 2-in-1?',
    a: 'One free account gives you two sales channels: your own branded booking website (yourclub.bookboll.com) where you can welcome your own customers, plus a listing on the Bookboll marketplace where players searching near you can discover and book your facility. Both channels share one dashboard, one calendar and one wallet.' },
  { q: 'Do I need my own website to use Bookboll?',
    a: 'No. Bookboll gives every business a free branded booking website on its own subdomain — with hourly court booking, live availability and online payments built in. Membership contact listings on your own website require Premium. Already have a website? Embed the Bookboll booking widget or add a booking button to it instead.' },
  { q: 'Can I use my own custom domain?',
    a: 'Yes. Your free site lives at yourbrand.bookboll.com, and you can connect a custom domain like yourclub.com at any time for a one-time fee — your logo, colours and languages stay yours either way.' },
  { q: 'How do payouts work?',
    a: 'You add a payout method — such as Stripe or the Bookboll wallet, depending on wallet type and country — to your Bookboll payout wallet, set up per country so each country pays out in its own currency. Membership customers arrange payment directly with the academy; Bookboll has no membership payout wallet. Your share of online payments is credited to your wallet; anything paid on arrival you collect directly at the venue.' },
  { q: 'How do online deposits work?',
    a: 'A deposit is part of the price, not an extra charge: the customer pays the deposit online to confirm the booking, it counts toward their total, and they pay only the remaining balance when they arrive. On both your website and the marketplace, Bookboll keeps the online deposit as its fee and you collect the remaining balance on arrival. This works with or without connected payouts. Full payment online needs connected payouts: Bookboll deducts its commission and credits your share to your Bookings wallet. Paid Premium uses your market’s Premium rate for own-website bookings; check your listing’s payment settings for the rate.' },
  { q: 'What can I list on Bookboll?',
    a: 'Courts and pitches for hourly rental (padel, football, tennis, basketball, badminton, volleyball and more), full venues, gyms, classes and academy contact listings, activity venues like escape rooms, billiards and bowling — plus games, hangouts and tournaments hosted at your venue.' },
  { q: 'Does Bookboll support gym memberships and subscriptions?',
    a: 'Yes. Advertise your gym or academy and show a contact phone so interested customers can speak to you directly. Marketplace exposure costs USD 20 per listing per month by default, with country or city rates where configured, on every plan. Premium includes membership listings on your own website. Bookboll does not enrol or bill academy customers.' },
  { q: 'Does Bookboll include marketing tools?',
    a: 'Yes. You can run WhatsApp and email campaigns to customers who opted in to marketing, customise notification templates, and add your own tracking (Meta Pixel, GA4, Google Tag Manager) to your branded website. Some advanced tools — like email campaigns, promo codes and homepage banners — are part of the Premium plan ($588/year, billed annually with no free trial).' },
  { q: 'Can my team have their own accounts?',
    a: 'Yes. Invite staff with Owner, Manager or Staff roles, grant or revoke individual permissions, and scope each person to specific locations, listings or programs — so the front desk can run the calendar without touching payouts.' },
  { q: 'How long does it take to set up?',
    a: 'Create your account, verify your email, add your venue and listings in the dashboard, choose your payment methods and share your link. Deposit + on arrival works without connected payouts. Full online booking payments need connected payouts. Membership listings show your contact phone; academy customers arrange payment directly with you.' },
  { q: 'Do my customers need to download an app?',
    a: 'No. Your booking site and the Bookboll marketplace both run in the browser on any phone or computer — customers book in a few taps.' },
]

// SoftwareApplication JSON-LD — describes the product itself; served alongside the FAQPage
// LD (useSeo stringifies the array into one valid JSON-LD script tag).
const APP_LD = {
  '@context': 'https://schema.org',
  '@type': 'SoftwareApplication',
  name: 'Bookboll for Business',
  applicationCategory: 'BusinessApplication',
  operatingSystem: 'Web',
  url: `https://business.${BRAND_APEX}/`,
  description: 'Booking software and a free branded website for sports venues, gyms and academies: hourly court rental, academy contact listings, online payments, marketing tools and marketplace exposure.',
  offers: {
    '@type': 'Offer',
    price: '0',
    priceCurrency: 'USD',
    description: 'No monthly subscription on Free. Booking commissions apply on both channels; own-website fees follow your market’s Free or paid Premium rate.',
  },
  publisher: { '@type': 'Organization', name: 'Bookboll', url: `https://${BRAND_APEX}/` },
}

useSeo({
  exactTitle: 'Booking Software & Free Website for Sports Venues, Gyms & Academies | Bookboll for Business',
  description: 'Free booking software for sports venues, gyms and academies: your own branded booking website, memberships, online payments and marketing tools. Booking commissions apply; Premium adds own-website membership listings and your market’s Premium booking fee rate.',
  path: '/',
  jsonLd: [APP_LD, faqLd(FAQS)],
})

const YEAR = new Date().getFullYear()
// Mirrors the REAL funnel: signup wizard (account → optional website) → dashboard
// (location + listing/program) → payout wallet → live.
const steps = [
  { icon: UserPlus, title: 'Create your account', sub: 'Choose your business address and verify your email.' },
  { icon: Globe, title: 'Set up your website', sub: 'Logo & colours — your address is already reserved. Skippable.', opt: true },
  { icon: MapPin, title: 'Add your first listing', sub: 'Venue, courts or programs — in your dashboard.' },
  { icon: Wallet, title: 'Choose payments & go live', sub: 'Set your payment options and share your link.' },
]

const siteThemes = [{name:'Ocean',color:'#245fce',pale:'#e8f0ff'},{name:'Forest',color:'#177455',pale:'#e7f4ed'},{name:'Plum',color:'#88486f',pale:'#f4eaf0'}]
const siteTheme = ref(siteThemes[0])
const activeWorkflow = ref('bookings')
const workflows = [
  { key: 'bookings', icon: CalendarCheck, title: 'Run your bookings', description: 'See availability, add walk-ins and keep every court or room on the same calendar.', items: ['Set opening hours and booking lengths', 'Offer peak-time prices and session extensions', 'Give your team access to the right locations'] },
  { key: 'payments', icon: CreditCard, title: 'Keep payments clear', description: 'Let customers pay online or pay a deposit and settle the rest when they arrive.', items: ['Show the full price before confirmation', 'Track payment status beside each booking', 'Connect payouts for full online payments'] },
  { key: 'memberships', icon: Repeat, title: 'Showcase your academy', description: 'Let interested customers find your programme and contact you directly.', items: ['Marketplace: monthly subscription per listing', 'Own website: included with Premium', 'Add members offline; manage attendance and cancellations', 'Record offline payments without a gateway'] },
]
function moveWorkflow(event,key) {
  if (!['ArrowRight','ArrowLeft','ArrowUp','ArrowDown','Home','End'].includes(event.key)) return
  event.preventDefault()
  const index = workflows.findIndex(w => w.key === key)
  const next = event.key === 'Home' ? 0 : event.key === 'End' ? workflows.length - 1 : (index + (['ArrowRight','ArrowDown'].includes(event.key) ? 1 : -1) + workflows.length) % workflows.length
  activeWorkflow.value = workflows[next].key
  event.currentTarget.parentElement.querySelector(`#tab-${activeWorkflow.value}`)?.focus()
}
const workflow = computed(() => workflows.find(w => w.key === activeWorkflow.value))
</script>

